import {getAction} from '@madou/catalog';
import {createGame,gameStats,transition,allCardInstanceIds,type GameCommand} from '@madou/engine';
import {assignCharacter,entropy,takeCard,trimHand,readySetup} from './scenario-tools.js';
export const blackBreakCard='a2-p09-r1c2';
export const blackBreakScenarios=['black-break-ordinary','black-break-guard','black-break-owner-ordinary','black-break-low','black-break-dedicated','black-break-far','black-break-same-faction','black-break-nonwhite','black-break-lower','black-break-white-equal','black-break-white-lower','black-break-front-white','black-break-back-white','black-break-wall-first','black-break-maai','black-break-evade','black-break-fate','black-break-suppressed','black-break-silenced','black-break-stopped','black-break-wrong-owner','black-break-decline','black-break-noncounter'] as const;
export type BlackBreakScenario=typeof blackBreakScenarios[number];
export function isBlackBreakScenario(name:string):name is BlackBreakScenario{return (blackBreakScenarios as readonly string[]).includes(name);}
export function blackBreakMode(name:BlackBreakScenario){const suffix=name.replace('black-break-',''),dedicated=!['ordinary','guard','owner-ordinary','low','white-equal','decline'].includes(suffix),owner=dedicated&&suffix!=='wrong-owner'||suffix==='owner-ordinary',followers=['ordinary','low','decline'].includes(suffix)?[]:({nonwhite:['a2-p22-r1c1'],lower:['a2-p19-r1c3'],'white-equal':['a2-p20-r2c2'],'white-lower':['a2-p20-r2c2'],'front-white':['a2-p22-r3c3','a2-p19-r1c3'],'back-white':['a2-p19-r1c3','a2-p22-r3c3'],'wall-first':['a2-p22-r1c1','a2-p22-r3c3']} as Record<string,string[]>)[suffix]??['a2-p22-r3c3'];return {suffix,dedicated,owner,followers};}
export function makeBlackBreakPhysical(name:BlackBreakScenario,players:{id:string;name:string}[],options:{beforeStart?:boolean;warrior?:number;spirit?:number}={}){
 const m=blackBreakMode(name),prior=['suppressed','stopped','silenced'].includes(m.suffix),incoming=m.suffix==='noncounter';let s=createGame(players,entropy(),{startingSeat:prior?3:incoming?1:0});const [a,b,c,d]=players.map(p=>p.id) as [string,string,string,string];
 for(const [i,p] of players.entries())assignCharacter(s,p.id,[m.owner?'黒騎士ガーウィン':'侍大将のシン',m.owner?'侍大将のシン':'獣使いのウパニシャット','黒妖精のアーネス','聖騎士ランスロット'][i]!);
 for(const p of Object.values(s.players)){p.permanent={endurance:100,warrior_level:20,magic_level:20,spirit:20};p.permanent.spirit!+=(p.id===a?options.spirit??6:6)-gameStats(s,p.id).spirit;}
 s.players[a]!.permanent!.warrior_level!+=(options.warrior??(m.suffix==='low'?3:m.dedicated?0:4))-gameStats(s,a).warrior_level;
 const keep=[takeCard(s,a,blackBreakCard),takeCard(s,a,'a2-p24-r1c3'),takeCard(s,d,'a2-p02-r2c3')];for(const id of m.followers)keep.push(takeCard(s,b,id));if(m.followers.length)keep.push(takeCard(s,c,'a2-p18-r3c3'));if(m.followers.length===2)keep.push(takeCard(s,d,'a2-p01-r2c1'));
 if(m.suffix==='same-faction')keep.push(takeCard(s,a,'a2-p24-r2c1'));if(m.suffix==='maai')keep.push(takeCard(s,b,'a2-p06-r1c3'));if(m.suffix==='evade')keep.push(takeCard(s,b,'a2-p05-r3c1'));if(incoming)keep.push(takeCard(s,b,'a2-p24-r1c2'));if(prior)keep.push(takeCard(s,d,m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1'));
 for(const p of players)trimHand(s,p.id,...keep);s.deck=[...s.deck.filter(id=>getAction(id)!.category!=='open'),...s.deck.filter(id=>getAction(id)!.category==='open')];if(m.followers.length===2){s.players[d]!.hand=s.players[d]!.hand.filter(id=>id!=='a2-p01-r2c1');s.deck.unshift('a2-p01-r2c1');}s.events=[];
 function act(actorId:string,command:GameCommand,face=1){const input={actorId,command},e={...entropy(),dice:Array(100).fill(face)},r=transition(s,input,e);if(!r.ok)throw Error(`BLACK_BREAK_FIXTURE_${command.type}_${r.code}`);if(JSON.stringify(r)!==JSON.stringify(transition(JSON.parse(JSON.stringify(s)),input,e)))throw Error('BLACK_BREAK_FIXTURE_REPLAY');s=r.state;const ids=allCardInstanceIds(s);if(ids.length!==220||new Set(ids).size!==220)throw Error('BLACK_BREAK_FIXTURE_CARDS');}
 function settle(face=1){for(let n=0;n<600;n++){const w=s.windows?.at(-1);if(!w)return;act(w.participants[w.cursor]!,{type:'PASS'},face);}throw Error('BLACK_BREAK_FIXTURE_LIMIT');}
 for(const id of [a,b,c,d]){if(id===b)for(const cardInstanceId of m.followers)act(b,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId});if(id===c&&m.followers.length)act(c,{type:'PLACE_INITIAL_FOLLOWER',cardInstanceId:'a2-p18-r3c3'});act(id,{type:'PASS_SETUP'});}readySetup(()=>s,id=>act(id,{type:'PASS_SETUP'}));if(options.beforeStart)return s;
 if(prior){act(d,{type:'START_TURN'});settle();act(d,{type:'CHOOSE_DRAW',draw:false});act(d,{type:'ATTACK',cardInstanceId:m.suffix==='suppressed'?'a2-p13-r1c2':m.suffix==='stopped'?'a2-p13-r2c1':'a2-p18-r1c1',targetIds:[a],dedicated:false});settle(6);if(s.phase==='withdrawal')act(d,{type:'PASS_WITHDRAWAL'});act(d,{type:'END_TURN',discardIds:[]});settle();}
 const starter=incoming?b:a;act(starter,{type:'START_TURN'});settle(prior?6:1);if(s.phase==='draw')act(starter,{type:'CHOOSE_DRAW',draw:false});if(incoming){act(b,{type:'ATTACK',cardInstanceId:'a2-p24-r1c2',targetIds:[a],dedicated:false});for(let n=0;n<400;n++){const w=s.windows!.at(-1)!;if(w.kind==='normal-defense')return s;act(w.participants[w.cursor]!,{type:'PASS'});}throw Error('BLACK_BREAK_FIXTURE_COUNTER_LIMIT');}
 if(!['far','stopped'].includes(m.suffix)){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r1c3',targetId:b});settle();}if(m.suffix==='same-faction'){act(a,{type:'APPROACH',cardInstanceId:'a2-p24-r2c1',targetId:c});settle();act(c,{type:'REVEAL_CHARACTER'});settle();}return s;
}
